    "insights.eyebrow": {en:"Insights",zh:"技术文章",es:"Artículos",ru:"Статьи",ar:"مقالات",tr:"İçgörüler",fr:"Articles",pt:"Artigos",hi:"लेख",id:"Wawasan"},
    "insights.title": {en:"HVAC Duct Machinery Engineering Guides",zh:"暖通风管设备工程指南",es:"Guías de Ingeniería de Maquinaria HVAC",ru:"Инженерные руководства по оборудованию воздуховодов",ar:"أدلة هندسية لآلات مجاري الهواء HVAC",tr:"HVAC Kanal Makineleri Mühendislik Kılavuzları",fr:"Guides d'ingénierie des machines de canalisation HVAC",pt:"Guias de Engenharia de Máquinas HVAC",hi:"HVAC डक्ट मशीनरी इंजीनियरिंग गाइड",id:"Panduan Teknik Mesin Saluran HVAC"},
    "insights.lead": {en:"Practical, engineer-led guides on HVAC ductwork machinery — written for buyers, fabricators and factory planners by the SBKJ Engineering team in Jiangyin, China.",zh:"由中国江阴SBKJ工程团队撰写，面向采购商、加工厂和工厂规划师的实用工程师指南。",es:"Guías prácticas dirigidas por ingenieros sobre maquinaria de conductos HVAC — escritas para compradores, fabricantes y planificadores por el equipo de Ingeniería de SBKJ en Jiangyin, China.",ru:"Практические инженерные руководства по оборудованию воздуховодов — для покупателей, производителей и проектировщиков от команды инженеров SBKJ в Цзянъине, Китай.",ar:"أدلة عملية يقودها المهندسون حول آلات مجاري الهواء HVAC — مكتوبة للمشترين والمصنعين ومخططي المصانع من قبل فريق هندسة SBKJ في جيانغيين، الصين.",tr:"HVAC kanal makineleri üzerine pratik, mühendis liderliğindeki kılavuzlar — Jiangyin, Çin'deki SBKJ Mühendislik ekibi tarafından alıcılar, üreticiler ve fabrika planlamacıları için yazılmıştır.",fr:"Guides pratiques dirigés par des ingénieurs sur les machines de canalisation HVAC — écrits pour les acheteurs, fabricants et planificateurs par l'équipe d'ingénierie SBKJ à Jiangyin, Chine.",pt:"Guias práticos liderados por engenheiros sobre máquinas de dutos HVAC — escritos para compradores, fabricantes e planejadores pela equipe de Engenharia SBKJ em Jiangyin, China.",hi:"HVAC डक्टवर्क मशीनरी पर व्यावहारिक, इंजीनियर-नेतृत्व वाले मार्गदर्शिकाएँ — SBKJ इंजीनियरिंग टीम द्वारा चीन के जियांगयिन में खरीदारों, फैब्रिकेटर्स और फैक्ट्री प्लानर्स के लिए लिखी गई।",id:"Panduan praktis yang dipimpin insinyur tentang mesin saluran HVAC — ditulis untuk pembeli, fabrikator, dan perencana pabrik oleh tim Teknik SBKJ di Jiangyin, Tiongkok."},
    "insights.clusters.eyebrow": {en:"Topic clusters",zh:"主题分类",es:"Grupos temáticos",ru:"Тематические кластеры",ar:"مجموعات المواضيع",tr:"Konu kümeleri",fr:"Groupes thématiques",pt:"Grupos temáticos",hi:"विषय समूह",id:"Klaster topik"},
    "insights.clusters.title": {en:"Five Topic Clusters Inside the SBKJ Insights Library",zh:"SBKJ技术文章库的五大主题分类",es:"Cinco Grupos Temáticos en la Biblioteca de Artículos SBKJ",ru:"Пять тематических кластеров в библиотеке статей SBKJ",ar:"خمسة مجموعات مواضيع داخل مكتبة مقالات SBKJ",tr:"SBKJ İçgörü Kütüphanesindeki Beş Konu Kümesi",fr:"Cinq groupes thématiques dans la bibliothèque d'articles SBKJ",pt:"Cinco Grupos Temáticos na Biblioteca de Artigos SBKJ",hi:"SBKJ लेख लाइब्रेरी के पांच विषय समूह",id:"Lima Klaster Topik di Perpustakaan Wawasan SBKJ"},

